        string symbol = this.safeString(trade, "symbol");
        string? messageHash = this.getMessageHash("trade", null, symbol);
        ccxt.pro.ArrayCache stored = ((ccxt.pro.ArrayCache)this.safeValue(this.trades, symbol));
        if ((stored == null))
        {
